VALUES
  (94, true, '94|||מרכז לאומי מוביל לצמצום תופעת ההתמכרויות ונזקיה. טיפול, מידע והכוונה למי שמתמודד עם התמכרות', '94|||מרפאה להתמכרויות: טיפול רפואי, וגם פסיכותרפיה. במרפאה.', '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"2018","meeting":"in_person","specialty":"התמכרויות, וגם פוסט־טראומה, קשב ודיכאון כשהם באים עם ההתמכרות","approaches":"גישה מוטיבציונית, טיפול מיודע טראומה, חיזוק קהילתי, מזעור נזקים, CBT, פסיכודינמית","languages":"","notes":"מרפאת מבוגרים, מרפאת נוער «נטע», ותוכנית מעג״ל. גם הכשרה, מחקר ומניעה. הצורן 2, נתניה.","target":"מבוגרים ונוער","org":"ICA – המרכז הישראלי להתמכרויות ובריאות הנפש","svc":"מרפאה להתמכרויות: טיפול רפואי, וגם פסיכותרפיה. במרפאה.","region":"נתניה","phone":"09-9789510","phoneLabel":"כללי","phoneShowNumber":false,"phone2":"09-9789500","phoneLabel2":"מרפאה","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@ica.org.il","emailLabel":"כללי","emailShowAddress":false,"email2":"clinic@ica.org.il","emailLabel2":"מרפאה","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"2018","meeting":"in_person","specialty":"Addictions, and also post-trauma, ADHD, and depression when they come with the addiction","approaches":"Motivational interviewing, trauma-informed care, community reinforcement, harm reduction, CBT, psychodynamic therapy","languages":"","notes":"An adult clinic, the Neta youth clinic, and the Maagal program. Also training, research, and prevention. 2 HaTzuran St, Netanya.","target":"Adults and youth","org":"ICA – Israel Center on Addiction and Mental Health","svc":"An addiction clinic: medical treatment, and also psychotherapy. At the clinic.","region":"Netanya","phone":"09-9789510","phoneLabel":"General","phone2":"09-9789500","ph