  (95, true, '95|||מרכז גמילה הוליסטי לטיפול בהתמכרויות (סמים, אלכוהול, הימורים ועוד) המבוסס על 12 הצעדים וגישות טיפוליות נוספות', '95|||מרכז גמילה פרטי: פסיכותרפיה, ולעיתים גם מעקב פסיכיאטרי. בשהייה מלאה במרכז.', '{"whatsapp":"","whatsappLabel":"","cost":"פרטי","founded":"","meeting":"in_person","specialty":"סמים, אלכוהול, הימורים","approaches":"12 הצעדים, גישות רוחניות","languages":"","notes":"עמותת צעדים «אחרת». עד 15 מטופלים. העצמאות 34, אור עקיבא.","target":"","org":"אחרת","svc":"מרכז גמילה פרטי: פסיכותרפיה, ולעיתים גם מעקב פסיכיאטרי. בשהייה מלאה במרכז.","region":"אור עקיבא","phone":"050-2244220","phoneLabel":"פניות","phoneShowNumber":false,"phone2":"050-5350387","phoneLabel2":"פניות","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"beniaheret@gmail.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"Private","founded":"","meeting":"in_person","specialty":"Drugs, alcohol, gambling","approaches":"The 12 steps, spiritual approaches","languages":"","notes":"The Tzeadim Acheret association. Up to 15 patients. 34 HaAtzmaut St, Or Akiva.","target":"","org":"Acheret","svc":"A private addiction center: psychotherapy, and sometimes also psychiatric follow-up. A full stay at the center.","region":"Or Akiva","phone":"050-2244220","phoneLabel":"Inquiries","phone2":"050-5350387","phoneLabel2":"Inquiries","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"beniaheret@gmail.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '22.11.2026: נבדק מול https://hacheret.com/. הניסוח אושר עם אצוות ההתמכרויות.'),
