  (248, true, '248|||טיפול בנפגעי אלכוהול, הימורים והתמכרויות התנהגותיות נוספות — למכורים ולבני משפחותיהם; הסברה ומניעה', '248|||טיפול בהתמכרות לאלכוהול, להימורים ולהתמכרויות התנהגותיות, למכורים ולבני משפחה. במרכז.', '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"","meeting":"in_person","specialty":"אלכוהול, הימורים, קניות, עבודה, אינטרנט","approaches":"","languages":"","notes":"במרכז רמת גן יש גם פסיכיאטר. גם הרצאות הסברה לנוער ולמבוגרים. במרכז מתארחות קבוצות GA וקבוצת צעדים. קו ההימורים הוא מיזם עם מפעל הפיס. ארלוזרוב 1, רמת גן.","target":"מכורים ובני משפחה","org":"עמותת אפשר","svc":"טיפול בהתמכרות לאלכוהול, להימורים ולהתמכרויות התנהגותיות, למכורים ולבני משפחה. במרכז.","region":"רמת גן, רחובות, ירושלים, ראש פינה","phone":"03-6733228","phoneLabel":"יחידה","phoneShowNumber":false,"phone2":"1-700-500-888","phoneLabel2":"הימורים","phoneShowNumber2":false,"phone3":"03-5026033","phoneLabel3":"משרד","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"efsharrg@netvision.net","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"","founded":"","meeting":"in_person","specialty":"Alcohol, gambling, shopping, work, the internet","approaches":"","languages":"","notes":"The Ramat Gan center also has a psychiatrist. Also information talks for youth and adults. GA groups and a steps group meet at the center. The gambling line is a joint project with Mifal HaPais. 1 Arlozorov St, Ramat Gan.","target":"People with an addiction and family members","org":"Efshar Association","svc":"Treatment for addiction to alcohol, gambling, and behavioral addictions, for the person and for the family. At the center.","region":"Ramat Gan, Rehovot, Jerusalem, Rosh Pina","phone":"03-6733228","phon