  (250, true, '250|||מרכז ברישיון משרד הבריאות לטיפול בהתמכרויות — בית מאזן לתחלואה כפולה, מרפאת יום, גמילה ותמיכה למשפחות; בשיתוף קופות החולים', '250|||טיפול בהתמכרויות ובתחלואה כפולה: פסיכותרפיה, עם פסיכיאטרים בצוות. בבית מאזן או במרפאת יום.', '{"whatsapp":"","whatsappLabel":"","cost":"בשיתוף קופות החולים","founded":"","meeting":"in_person","specialty":"תחלואה כפולה, סמים, אלכוהול, הימורים, מין, אינטרנט, הפרעות אכילה","approaches":"טיפול מיודע טראומה, CBT, מיינדפולנס, גוף־נפש, טיפול באמנויות, פסיכודרמה","languages":"","notes":"רישיון משרד הבריאות. בית המאזן לגברים. יש שילוב של המשפחה, וליווי אחרי הטיפול. ההדס 4, בית שמש.","target":"","org":"דרך אחרת","svc":"טיפול בהתמכרויות ובתחלואה כפולה: פסיכותרפיה, עם פסיכיאטרים בצוות. בבית מאזן או במרפאת יום.","region":"בית שמש","phone":"02-6661166","phoneLabel":"משרד","phoneShowNumber":false,"phone2":"054-5553370","phoneLabel2":"נייד","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"office@acher.org.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"whatsapp":"","whatsappLabel":"","cost":"In cooperation with the health funds","founded":"","meeting":"in_person","specialty":"Dual diagnosis, drugs, alcohol, gambling, sex, the internet, eating disorders","approaches":"Trauma-informed care, CBT, mindfulness, mind-body therapy, arts therapy, psychodrama","languages":"","notes":"Licensed by the Ministry of Health. The balancing home is for men. The family is part of the treatment, and there is follow-up after it ends. 4 HaHadas St, Beit Shemesh.","target":"","org":"Derech Acheret","svc":"Treatment for addictions and dual diagnosis: psychotherapy, with psychiatrists on the team. In a balancing home or in the day cli